import{_ as o,C as r,c as s,o as a,a3 as t,G as l}from"./chunks/framework.Dokpd4od.js";const f=JSON.parse('{"title":"Bill sequence","description":"","frontmatter":{},"headers":[],"relativePath":"master/finance/vendor-bills/bill-sequence.md","filePath":"master/finance/vendor-bills/bill-sequence.md","lastUpdated":1793074831000}'),i={name:"master/finance/vendor-bills/bill-sequence.md"};function u(c,e,d,h,g,m){const n=r("ImagePopup");return a(),s("div",null,[e[0]||(e[0]=t('<h1 id="bill-sequence" tabindex="-1">Bill sequence <a class="header-anchor" href="#bill-sequence" aria-label="Permalink to &quot;Bill sequence&quot;">​</a></h1><p>Every vendor bill gets a number when you save it, for example <code>BILL/2026/4</code>. Aureus builds this number from a sequence that belongs to the <strong>Vendor Bills</strong> journal. Knowing how it works helps you read your numbers and fix them when needed.</p><blockquote><p><strong>In simple words:</strong> The bill number is made by a counter. The counter belongs to the Vendor Bills journal and starts again each year.</p></blockquote><h2 id="how-a-bill-number-is-made" tabindex="-1">How a bill number is made <a class="header-anchor" href="#how-a-bill-number-is-made" aria-label="Permalink to &quot;How a bill number is made&quot;">​</a></h2><p>A number has three parts: a prefix, the year and a counter.</p><ul><li><strong>Prefix:</strong> The journal code. For vendor bills the code is <code>BILL</code>.</li><li><strong>Year:</strong> The year of the accounting date, for example <code>2026</code>.</li><li><strong>Counter:</strong> A number that grows by one with each bill. New sequences pad it to five digits.</li></ul><p>A new bill is therefore numbered like <code>BILL/2026/00005</code>. Older seed data may show shorter counters, such as <code>BILL/2026/4</code>. Both forms are valid.</p><p>The default prefix is <code>{journal code}/{year}/</code>. For the Vendor Bills journal, that is <code>BILL/%(year)/</code>.</p><h2 id="reset-every-year" tabindex="-1">Reset every year <a class="header-anchor" href="#reset-every-year" aria-label="Permalink to &quot;Reset every year&quot;">​</a></h2><p>The counter is set to restart <strong>Every Year</strong>. The first bill of 2027 becomes <code>BILL/2027/00001</code>. You can change this rule in the sequence.</p><h2 id="refund-numbers" tabindex="-1">Refund numbers <a class="header-anchor" href="#refund-numbers" aria-label="Permalink to &quot;Refund numbers&quot;">​</a></h2><p>A refund is a bill you reverse with the <strong>Refund</strong> button. Its number depends on the journal.</p><ul><li>If the journal has <strong>Dedicated Credit Note Sequence</strong> on, refunds use their own counter. Their prefix gets an <code>R</code>, so you see <code>RBILL/2026/00006</code>.</li><li>If the toggle is off, refunds share the counter of the bills.</li></ul><p>Set this toggle in <code>Accounting → Configurations → Accounting → Journals</code>. Open the <strong>Vendor Bills</strong> journal and find it under <strong>Accounting Information</strong>. See <a href="./../get-started/journals.html">Journals</a>.</p><h2 id="see-and-change-the-sequence" tabindex="-1">See and change the sequence <a class="header-anchor" href="#see-and-change-the-sequence" aria-label="Permalink to &quot;See and change the sequence&quot;">​</a></h2><ol><li>Go to <code>Settings → Sequences</code>.</li><li>Find the rows <strong>Vendor Bills</strong> and <strong>Vendor Bills (Refund)</strong>.</li><li>Check <strong>Next Document Number</strong> to see the number the next bill gets.</li><li>Click <strong>Edit</strong> to change it.</li></ol><p>The list shows <strong>Name</strong>, <strong>Code</strong>, <strong>Applies To</strong>, <strong>Company</strong>, <strong>Next Document Number</strong>, <strong>Next Number</strong> and <strong>Reset Counter</strong>. In the example data, <strong>Vendor Bills</strong> shows <code>BILL/2026/00005</code> and <strong>Vendor Bills (Refund)</strong> shows <code>RBILL/2026/00006</code>.</p>',17)),l(n,{src:"/images1/finance/bill_sequences_list.png",alt:"Sequences list with the Vendor Bills and Vendor Bills (Refund) rows and their next document numbers"}),e[1]||(e[1]=t('<p>On the edit form you can change the <strong>Name</strong>, <strong>Prefix</strong>, <strong>Suffix</strong>, <strong>Number Padding</strong>, <strong>Next Number</strong>, <strong>Step</strong> and <strong>Reset Counter</strong>. See <a href="./../../general-settings/customization/sequences.html">Sequences</a> for every field.</p><h2 id="rules-for-next-number" tabindex="-1">Rules for Next Number <a class="header-anchor" href="#rules-for-next-number" aria-label="Permalink to &quot;Rules for Next Number&quot;">​</a></h2><ul><li>You can only raise <strong>Next Number</strong>. You cannot lower it.</li><li>Aureus checks this so two bills never share a number.</li><li>To skip numbers, enter a higher value. The next bill uses it.</li><li>Deleting the sequence does not restart at 1. Aureus rebuilds it after the highest number that exists.</li></ul><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>Do not lower a counter to reuse numbers. Posted bills keep their numbers, and gaps in a series are normal.</p></div><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Customer invoices work the same way, with the code <code>INV</code>. See <a href="./../customer-invoices/invoice-sequence.html">Invoice sequence</a>.</p></div><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="./create-bill.html">Create a vendor bill</a></li><li><a href="./../customer-invoices/invoice-sequence.html">Invoice sequence</a></li><li><a href="./../../general-settings/customization/sequences.html">Sequences</a></li><li><a href="./../get-started/journals.html">Journals</a></li></ul>',7))])}const p=o(i,[["render",u]]);export{f as __pageData,p as default};
